define('taoQtiItem/qtiXmlRenderer/renderers/responses/SimpleFeedbackRule',['lodash', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/rule', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/rule_condition', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/rule_condition_score', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/rule_correct', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/rule_incorrect', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/rule_isnull', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/rule_choices'], function (_, tpl, tplCondition, tplConditionScore, tplCorrect, tplIncorrect, tplIsnull, tplChoices) {
  return {
    qtiClass: '_simpleFeedbackRule',
    template: tpl,
    getData: function getData(rule, data) {
      var template = null,
        ruleXml = '';
      var _values;
      var tplData = {
        response: rule.comparedOutcome.id(),
        feedback: {
          'outcome': rule.feedbackOutcome.id(),
          'then': rule.feedbackThen.id(),
          'else': rule.feedbackElse ? rule.feedbackElse.id() : ''
        }
      };
      switch (rule.condition) {
        case 'correct':
          template = tplCorrect;
          break;
        case 'incorrect':
          template = tplIncorrect;
          break;
        case 'isNull':
          template = tplIsnull;
          break;
        case 'lt':
        case 'lte':
        case 'equal':
        case 'gte':
        case 'gt':
          template = tplCondition;
          tplData.condition = rule.condition;
          tplData.comparedValue = rule.comparedValue;
          break;
        case 'score.lt':
        case 'score.lte':
        case 'score.equal':
        case 'score.gte':
        case 'score.gt':
          template = tplConditionScore;
          tplData.condition = rule.condition.replace('score.', '');
          tplData.comparedValue = rule.comparedValue;
          tplData.scoreIdentifier = data.scoreIdentifier || 'SCORE';
          break;
        case 'choices':
          template = tplChoices;
          tplData.condition = rule.condition;
          tplData.multiple = rule.comparedOutcome.isCardinality(['multiple', 'ordered']);
          _values = [];
          _.forEach(rule.comparedValue, function (choice) {
            if (choice.parent()) {
              _values.push(choice.id());
            }
          });
          if (tplData.multiple) {
            tplData.choices = _values;
          } else {
            if (_values.length) {
              tplData.choice = _.head(_values);
            } else {
              tplData.noData = true;
            }
          }
          break;
        default:
          throw new Error('unknown condition in simple feedback rule rendering : ' + rule.condition);
      }
      if (template) {
        ruleXml = template(tplData);
      }
      return _.merge(data || {}, {
        rule: ruleXml
      });
    }
  };
});
