define('taoQtiItem/qtiCreator/model/pciCreatorContext',['lodash'], function (_) {
  "use strict";

  var _pciModels = {};
  var pciCreatorContext = {
    register: function register(pciModel) {
      _pciModels[pciModel.getTypeIdentifier()] = pciModel;
    },
    createPciInstance: function createPciInstance(pciTypeIdentifier) {
      if (_pciModels[pciTypeIdentifier]) {
        return _.cloneDeep(_pciModels[pciTypeIdentifier]);
      }
    }
  };
  return pciCreatorContext;
});
